/**
 * Global and route IP list precedence parity with the reference engine
 * (guard_core/_utils/access_control.py `_check_ip_lists_detail`,
 * guard_core/core/checks/helpers.py `check_route_ip_access`): when a whitelist
 * is configured only the whitelist decides and the blacklist is not consulted;
 * the blacklist applies only when no whitelist is configured. The expectations
 * in ip-list-precedence-cases.json are generated by running the reference.
 */
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { isIpAllowed } from '../../src/utils.js';
import { checkIpAccess } from '../../src/core/checks/ip-access.js';
import { checkRouteIpAccess } from '../../src/core/checks/helpers.js';
import { SecurityConfigSchema } from '../../src/models/config.js';
import { RouteConfig } from '../../src/models/route-config.js';
import { initializeSecurityMiddleware } from '../../src/middleware-support.js';
import { defaultLogger } from '../../src/models/logger.js';
import type { GuardRequest } from '../../src/protocols/request.js';
import { createMockMiddleware, createMockResponseFactory } from '../helpers.js';

interface Row {
  whitelist: string[];
  blacklist: string[];
  ip: string;
  global: boolean;
  isAllowed: boolean;
  route: boolean | null;
}

const ROWS: Row[] = JSON.parse(
  readFileSync(new URL('./ip-list-precedence-cases.json', import.meta.url), 'utf8'),
);

function cfg(row: Row) {
  return SecurityConfigSchema.parse({
    enableRedis: false,
    whitelist: row.whitelist.length > 0 ? row.whitelist : null,
    blacklist: row.blacklist,
  });
}

const label = (r: Row) => `wl=${JSON.stringify(r.whitelist)} bl=${JSON.stringify(r.blacklist)} ip=${r.ip}`;

describe('IP list precedence matches the reference', () => {
  it.each(ROWS.map((r) => [label(r), r] as const))('global checkIpAccess %s', async (_l, r) => {
    expect((await checkIpAccess(r.ip, cfg(r))).allowed).toBe(r.global);
  });

  it.each(ROWS.filter((r) => r.ip !== 'unknown').map((r) => [label(r), r] as const))(
    'isIpAllowed %s',
    async (_l, r) => {
      expect(await isIpAllowed(r.ip, cfg(r))).toBe(r.isAllowed);
    },
  );

  it.each(ROWS.filter((r) => r.ip !== 'unknown').map((r) => [label(r), r] as const))(
    'route checkRouteIpAccess %s',
    async (_l, r) => {
      const rc = new RouteConfig();
      rc.ipWhitelist = r.whitelist.length > 0 ? r.whitelist : null;
      rc.ipBlacklist = r.blacklist.length > 0 ? r.blacklist : null;
      expect(await checkRouteIpAccess(r.ip, rc, createMockMiddleware())).toBe(r.route);
    },
  );
});

interface RouteGlobalRow {
  globalWhitelist: string[];
  globalBlacklist: string[];
  routeWhitelist: string[];
  routeBlacklist: string[];
  ip: string;
  allowed: boolean;
}

const ROUTE_GLOBAL_ROWS: RouteGlobalRow[] = JSON.parse(
  readFileSync(new URL('./ip-list-route-global-cases.json', import.meta.url), 'utf8'),
);

function request(ip: string, routeConfig: RouteConfig): GuardRequest {
  return {
    urlPath: '/api/test',
    urlScheme: 'https',
    urlFull: 'https://example.com/api/test',
    urlReplaceScheme: (s: string) => `${s}://example.com/api/test`,
    method: 'GET',
    clientHost: ip,
    headers: { 'user-agent': 'TestAgent/1.0' },
    queryParams: {},
    body: async () => new Uint8Array(0),
    state: { _routeConfig: routeConfig },
    scope: {},
  };
}

describe('route and global IP lists match the reference', () => {
  it('a configured route whitelist skips the global lists', async () => {
    const failures: string[] = [];
    for (const r of ROUTE_GLOBAL_ROWS) {
      const config = SecurityConfigSchema.parse({
        enableRedis: false,
        enableRateLimiting: false,
        whitelist: r.globalWhitelist.length > 0 ? r.globalWhitelist : null,
        blacklist: r.globalBlacklist,
      });
      const rc = new RouteConfig();
      rc.ipWhitelist = r.routeWhitelist.length > 0 ? r.routeWhitelist : null;
      rc.ipBlacklist = r.routeBlacklist.length > 0 ? r.routeBlacklist : null;
      const components = await initializeSecurityMiddleware(config, defaultLogger, createMockResponseFactory());
      const allowed = (await components.pipeline.execute(request(r.ip, rc))) === null;
      if (allowed !== r.allowed) failures.push(`${JSON.stringify(r)}: got ${allowed}`);
    }
    expect(failures).toEqual([]);
  });
});
